  function pdfInfo(row){const resolved=M?.resolve(row,{manifest:window.ELAB_PDF_SOURCE_MANIFEST,manualMappings:manualPdfMappings,programRoot:pdfServerRoot,origin:location.origin});if(resolved?.reference){const mapped=displayPdfUrl(resolved.reference);return {url:mapped.url,mapping_error:mapped.error,reference:resolved.reference,page:resolved.page,automatic:!['TEACHER_SOURCE_FILE_OVERRIDE'].includes(resolved.origin),origin:resolved.origin,source_format:resolved.source_format,status:resolved.status,candidates:resolved.candidates};}const source=row.auto.source.source_file,manual=localPdfs.get(source);return manual?{...manual,automatic:false,mapping_error:null,origin:'MANUAL_LOCAL_FILE'}:{...resolved,automatic:false};}
