  function pdfViewerMarkup(){return `<div class="pdf-custom-viewer" data-pdf-reviewer><div class="pdf-custom-toolbar" aria-label="PDF 검수 도구"><button data-pdf-zoom-out aria-label="PDF 축소">−</button><output data-pdf-zoom-label>100%</output><button data-pdf-zoom-in aria-label="PDF 확대">＋</button><button data-pdf-fit>화면 맞춤</button><button data-pdf-sentence>문장 위치</button><span class="pdf-page-controls"><button data-pdf-prev aria-label="이전 PDF 페이지">‹</button><output data-pdf-page-label>— / —</output><button data-pdf-next aria-label="다음 PDF 페이지">›</button></span><button data-pdf-retry hidden>다시 찾기</button></div><p class="pdf-custom-status loading" role="status">PDF 페이지를 여는 중입니다.</p><div class="pdf-custom-scroll" tabindex="0" aria-label="마우스로 끌어 이동할 수 있는 PDF"><div class="pdf-custom-stage"><canvas></canvas><div class="pdf-highlight-layer" aria-hidden="true"></div></div></div></div>`;}
  function mountPdfViewer(row){const host=$('[data-pdf-reviewer]'),info=pdfInfo(row);if(!host||!info?.url||!window.ReviewPdfViewer)return;window.ReviewPdfViewer.mount(host,{sentenceId:row.sentence_id,url:info.url,page:info.page,sentenceText:row.teacher.teacher_corrected_text??row.auto.text,onOpened:()=>markPdfOpened(row.sentence_id)});}
  function pdfMarkup(row){const info=pdfInfo(row),usable=!!info?.url,s=row.auto.source,t=row.teacher,visualReviewed=C.pdfReviewReady(t),verified=sourceConfirmed(row),review=t.teacher_source_pdf,opened=openedPdfs.has(row.sentence_id)||visualReviewed,candidates=info?.candidates||[];return `<details class="pdf-panel" open><summary>원본 PDF · ${esc(s.question_no||'문항번호 없음')}</summary><div class="pdf-meta"><b>${info?.origin==='GENERATED_MANIFEST'?'manifest 자동 연결':info?.automatic?'검증된 자동 연결':usable?'수동 로컬 선택':'자동 연결 없음'}</b><span>${esc(info?.reference||review?.pdf_reference||s.source_file)}</span><span>문항 ${esc(s.question_no||'미기록')} · ${info?.page?'PDF '+esc(info.page)+'페이지':'PDF page metadata 없음 · 첫 페이지에서 직접 문항 확인'}</span></div>${usable?`<div class="pdf-actions"><a class="button" data-pdf-open data-sentence="${esc(row.sentence_id)}" href="${esc(withPage(info.url,info.page))}" target="_blank" rel="noopener">새 창에서 PDF 열기</a><button data-source-one-click data-pdf-ready="${opened}" class="${verified?'gold':opened?'primary':'primary blocked'}" ${verified?'disabled':''}>${verified?'✓ PDF 원문 확인 완료':'✓ PDF 확인 · 원문 일치'}</button></div>${!opened?'<p class="help pdf-open-hint">검수용 PDF에서 강조된 문장을 확인하거나 새 창에서 원문을 여세요.</p>':''}${verified?`<p class="pdf-reviewed-status">✓ PDF 원문 확인 완료 · ${esc(reviewedTime(review.reviewed_at))}</p>`:visualReviewed?`<p class="pdf-reviewed-status pending">기존 PDF 확인 기록 있음 · 원문 일치를 확정해주세요.</p>`:''}${pdfViewerMarkup()}`:`<div class="pdf-empty"><p class="${info?.mapping_error?'pdf-mapping-error':''}">${esc(info?.mapping_error||'자동 연결 근거가 없습니다. PDF를 추측해 연결하지 않습니다.')}</p>${candidates.length?`<div class="pdf-candidates"><b>교사 선택 필요</b>${candidates.map((x,i)=>`<button data-pdf-candidate="${i}">${esc(x.basename||x.relative_path)}</button>`).join('')}</div>`:''}<label class="button" for="local-pdf-file">원문 PDF 선택</label><input id="local-pdf-file" type="file" accept=".pdf,application/pdf" hidden><p>선택한 PDF는 업로드하지 않고 이 브라우저의 전용 IndexedDB에 source_file 단위로 보관합니다. 같은 출처 문장과 F5 후에도 재사용하며, page metadata가 없으면 <b>${esc(s.question_no||'해당 문항')}</b>을 직접 찾으세요.</p></div>`}<p class="pdf-policy">노란 표시는 PDF에서 정확히 찾은 현재 문장 위치입니다. 자동 강조와 열람만으로 SOURCE_VERIFIED가 되지 않습니다.</p></details>`;}
  function findNextSentence(queue,fromId,delta=1,unreviewed=false){let i=queue.findIndex(x=>x.sentence_id===fromId);if(i<0)i=delta>0?-1:0;for(let n=1;n<=queue.length;n++){const next=queue[(i+delta*n+queue.length*2)%queue.length];if(next&&(!unreviewed||!['GOLD_READY','DEFERRED','REJECTED'].includes(C.status(next))))return next;}return null;}
